sys_variable_value.value:
(function execute(inputs, outputs) {
         var orchestrator = new FO_AIOrchestrator();
         var classification = orchestrator.classifyIntent(inputs.requestID);
         
         if (classification) {
             var caseIds = orchestrator.routeIntents(inputs.requestID, classification);
             outputs.classification_result = JSON.stringify(classification);
             outputs.cases_created = caseIds.length;
         } else {
             outputs.classification_result = '';
             outputs.cases_created = 0;
         }
     })(inputs, outputs);

